sys_security_acl.script:
// Users can only view their own leave requests
if (current.employee == gs.getUserID() || current.requested_by == gs.getUserID()) {
    answer = true;
}
// Managers can view their team's leave requests
else {
    var user = new GlideRecordSecure('sys_user');
    if (user.get(current.employee)) {
        if (user.manager == gs.getUserID()) {
            answer = true;
        }
    }
}

// HR admins can view all leave requests
if (gs.hasRole('x_1800027_leve_sys.leave_hr_admin')) {
    answer = true;
}
